#include <cmath>
#include <vector>
#include <array>
#include <string>
#include <fstream>
#include <iostream>
#include <iomanip>
#include <algorithm>
using D = std::vector<double>;
static std::istream &readvec(std::istream& f,D& v){return f.read(reinterpret_cast<char*>(v.data()),v.size()*sizeof(double));}
static std::array<double,4> cubic(double u) {
    return {{-u*(u-1)*(u-2)/6,(u+1)*(u-1)*(u-2)/2,-(u+1)*u*(u-2)/2,(u+1)*u*(u-1)/6}};
}
int main(int argc, char** argv){
    std::ifstream data(argv[1],std::ios::binary);int n=std::stoi(argv[2]),nt=std::stoi(argv[3]),np=std::stoi(argv[4]),nv=std::stoi(argv[5]);
    D header(5),drive(nt+1),chi(nt+1),tab(3*n*n);readvec(data,header);readvec(data,drive);readvec(data,chi);if(!readvec(data,tab)) return 1;
    double Lx=header[0],Ly=Lx*std::sqrt(3.),T=header[1],fac=header[2],kbT=header[3],sigma=header[4],dt=T/nt;
    double total[3]={},offset[3]={},velocity[3]={},base[3]={};
    const double strengths[]={0.,chi[0],1.};
    int mask=n-1,sz=2*np*nv; if(n & mask)return 2;
    D fy(n),fyy(n),u(n);
    auto makecol=[&](double x, int ch,D& col){
        double phase=x*n/Lx;int i=int(std::floor(phase));auto w=cubic(phase-i);
        for(int j=0;j<n;j++) {double val=0;for(int t=0;t<4;t++)val+=w[t]*tab[ch*n*n+n*((i+t-1)&mask)+j];col[j]=val;}
    };
    auto lookup=[&](double y,const D& col){
        double z=y*n/Ly;int j=int(std::floor(z));auto w=cubic(z-j);
        return w[0]*col[(j-1)&mask]+w[1]*col[j&mask]+w[2]*col[(j+1)&mask]+w[3]*col[(j+2)&mask];};
    D q(sz),v(sz),v0(sz),x1(sz,1),v1(sz),x2(sz),v2(sz,1),ai(sz),hi(sz),wt(3*sz);
    for(int a=0;a<np;a++){
        double x0=(a+.5)*Lx/np;
        makecol(x0,0,u);
        for(int b=0;b<2*np;b++) for(int h=0;h<nv;h++){
            int i=b*nv+h;
            q[i]=Ly*(b+.5)/(2*np);double z=-8+16.*(h+.5)/nv;
            v0[i]=v[i]=sigma*z; x1[i]=v2[i]=1.;x2[i]=v1[i]=0.;
            double e=lookup(q[i],u);
            for(int j=0;j<3;j++){wt[j*sz+i]=std::exp(-strengths[j]*(e+1.)/kbT-.5*z*z);total[j]+=wt[j*sz+i];}
        }
        for(int it=0;it<=nt;it++){
            makecol(x0+drive[it],1,fy);makecol(x0+drive[it],2,fyy);
            for(int i=0;i<sz;i++){
                if(it){q[i]+=dt*v[i]+.5*dt*dt*ai[i]; x1[i]+=dt*v1[i]+.5*dt*dt*hi[i]*x1[i]; x2[i]+=dt*v2[i]+.5*dt*dt*hi[i]*x2[i];}
                double acc= -fac*chi[it]*lookup(q[i],fy), deriv= -fac*chi[it]*lookup(q[i],fyy);
                if(it){v[i]+=.5*dt*acc;v1[i]+=.5*dt*deriv*x1[i];v2[i]+=.5*dt*deriv*x2[i];}
                ai[i]=acc;hi[i]=deriv;
                if(it<nt){
                    // Store half-kicked velocities; next drift above must use the
                    // full-step velocity (undo its separate acceleration term).
                    v[i]+=.5*dt*acc;v1[i]+=.5*dt*deriv*x1[i];v2[i]+=.5*dt*deriv*x2[i];
                    ai[i]=hi[i]=0.;
                }
            }
        }
        for(int i=0;i<sz;i++)for(int j=0;j<3;j++){
            const double w=wt[j*sz+i]; offset[j]-=w*v1[i];velocity[j]+=w*(v2[i]-1);base[j]+=w*(v[i]-v0[i]);
        }
    }
    std::cout<<std::setprecision(15);
    for(int j=0;j<3;j++)std::cout<<"{\"strength\":"<<strengths[j]<<",\"K\":"<<.01/T*offset[j]/total[j]<<",\"Z\":"<<.01/T*velocity[j]/total[j]<<",\"mean_impulse_flux\":"<<.01/T*base[j]/total[j]<<"}\n";
}
